// Analyse le format d'exposition Prometheus servi par Aigent et produit
// un verdict de flotte. AUCUN appel LLM : c'est de l'arithmétique.
//
// Règle de vérité : une métrique ABSENTE n'est pas un zéro. Si Aigent est
// injoignable ou n'a rien mesuré, le verdict est UNAVAILABLE — jamais
// « 0 run, tout va bien ».

const item = $input.first().json;

// Le nœud HTTP change de forme selon `fullResponse` : avec, on a
// {statusCode, body} ; sans, seulement {data}. On accepte les deux plutôt que
// de dépendre d'une option — un garde qui exige `statusCode` déclare
// faussement UNAVAILABLE alors que le corps est bien là (constaté le
// 2026-08-01 sur l'exécution n°2).
const status = item.statusCode ?? item.status ?? null;
const body = typeof item.body === 'string' ? item.body
  : typeof item.data === 'string' ? item.data
  : '';

// Le verdict se joue sur le CONTENU : un corps qui porte des métriques
// Aigent est une preuve plus forte qu'un code de statut.
const hasMetrics = body.includes('aigent_runs_total');
const statusBad = status !== null && status !== 200;

if (statusBad || !hasMetrics) {
  return [{ json: {
    verdict: 'UNAVAILABLE',
    reason: statusBad
      ? `source Aigent en erreur (HTTP ${status})`
      : 'réponse sans métrique Aigent exploitable',
    checkedAt: new Date().toISOString(),
    llmCallsBilled: 0,
  }}];
}

/** Lit une métrique sans label. Retourne null si absente — jamais 0. */
function gauge(name) {
  const m = body.match(new RegExp('^' + name + ' ([0-9.eE+-]+)$', 'm'));
  return m ? Number(m[1]) : null;
}

/** Lit une métrique labellisée par status. */
function byStatus(name, status) {
  const m = body.match(new RegExp('^' + name + '\\{status="' + status + '"\\} ([0-9.eE+-]+)$', 'm'));
  return m ? Number(m[1]) : null;
}

const totalRuns = gauge('aigent_runs_total');
const successRate = gauge('aigent_success_rate');
const p95 = gauge('aigent_run_latency_ms_p95');
const couples = gauge('aigent_reporting_agents');
const completed = byStatus('aigent_runs_by_status', 'completed');
const failed = byStatus('aigent_runs_by_status', 'failed');
const started = byStatus('aigent_runs_by_status', 'started');
const lastEvent = gauge('aigent_last_event_timestamp_seconds');

if (totalRuns === null) {
  return [{ json: {
    verdict: 'UNAVAILABLE',
    reason: 'aucune métrique de run exposée',
    checkedAt: new Date().toISOString(),
    llmCallsBilled: 0,
  }}];
}

// Seuils explicites, lisibles, sans magie.
const SUCCESS_FLOOR = 0.8;
const P95_CEILING_MS = 30000;

const alerts = [];
if (successRate !== null && successRate < SUCCESS_FLOOR) {
  alerts.push(`taux de succès ${(successRate * 100).toFixed(1)}% sous le plancher de ${SUCCESS_FLOOR * 100}%`);
}
if (p95 !== null && p95 > P95_CEILING_MS) {
  alerts.push(`p95 ${p95} ms au-dessus du plafond de ${P95_CEILING_MS} ms`);
}
if (successRate === null) {
  alerts.push('taux de succès non mesuré — absence, pas 0 %');
}

const ageHours = lastEvent !== null
  ? Math.round((Date.now() / 1000 - lastEvent) / 3600)
  : null;
if (ageHours !== null && ageHours > 48) {
  alerts.push(`dernier événement il y a ${ageHours} h — flotte possiblement silencieuse`);
}

return [{ json: {
  verdict: alerts.length === 0 ? 'HEALTHY' : 'ATTENTION',
  alerts,
  metrics: {
    totalRuns,
    completed,
    failed,
    started,
    successRate,
    p95LatencyMs: p95,
    reportingCouples: couples,
    lastEventAgeHours: ageHours,
  },
  provenance: {
    source: 'runtime_telemetry_events',
    producer: 'summarizeFleetRuntimeTelemetry()',
    route: '/api/agent-ops/metrics',
  },
  checkedAt: new Date().toISOString(),
  llmCallsBilled: 0,
}}];

// Artefact d'alerte. Volontairement local : aucun webhook sortant, aucun
// envoi externe non demandé. Ce que produit ce nœud est la charge utile
// qu'un canal réel (Slack, ticket) consommerait.
const j = $input.first().json;
return [{ json: {
  artifact: 'aigent-fleet-alert',
  severity: j.verdict === 'UNAVAILABLE' ? 'unknown' : 'warning',
  title: `Flotte Aigent — ${j.verdict}`,
  lines: j.alerts ?? [j.reason],
  metrics: j.metrics ?? null,
  provenance: j.provenance ?? null,
  checkedAt: j.checkedAt,
  llmCallsBilled: 0,
}}];

const j = $input.first().json;
return [{ json: {
  artifact: 'aigent-fleet-ok',
  severity: 'info',
  title: 'Flotte Aigent — conforme',
  metrics: j.metrics,
  provenance: j.provenance,
  checkedAt: j.checkedAt,
  llmCallsBilled: 0,
}}];
